 static void Advance(Simulation s,double seconds){double pending=seconds;int rounds=0;var timer=Stopwatch.StartNew();while(pending>1e-7&&rounds++<200000){pending=s.Advance(pending,512);if(timer.Elapsed.TotalSeconds>20){File.WriteAllText(Path.Combine(root,"Logs/Expansion/stalled.json"),JsonSerializer.Serialize(s.S,J));throw new Exception("Slow event boundary at "+s.S.time+" pending="+pending+" rounds="+rounds);}}if(pending>1e-7)throw new Exception("Unfinished simulation span");}
 static bool Near(BigDouble a,BigDouble b)=>BigDouble.Abs(a-b)/BigDouble.Max(1,BigDouble.Max(a,b))<1e-7;
 static Simulation Mature(){var s=new Simulation(data);for(int i=0;i<12;i++){s.S.resources[i]=BigDouble.Parse("1e18");s.S.lifetime[i]=BigDouble.Parse("1e18");}s.S.automation.buy=false;s.S.resets[0]=s.S.resets[1]=s.S.resets[2]=1;s.S.prestige[1]=new BigDouble(100);s.Meta.prestigeEarned=new BigDouble(1000);s.Meta.ascensionEarned=new BigDouble(1000);return s;}
