  var meta=Mature();Check("Energy tree prerequisite",!meta.BuyMeta("a_energy_2"));Check("Energy tree purchase",meta.BuyMeta("a_energy_1"));var invested=meta.S.prestige[1].Value;var earned=meta.Meta.ascensionEarned.Value;meta.RespecAscension();meta.RespecAscension();Check("free respec conserves point budget",meta.S.prestige[1].Value==invested+1&&meta.Meta.ascensionEarned.Value==earned);
  foreach(var law in ExpansionContent.Laws){meta.Meta.lawReadyAt=0;Check("law switch "+law.id,meta.SetLaws(new[]{law.id}));meta.RefreshRates();Check("law finite flow "+law.id,!BigDouble.IsNaN(meta.CachedFlow(0)));}Check("law cooldown enforced",!meta.SetLaws(new[]{"flux_radiance"}));meta.Meta.lawReadyAt=0;Check("law family collision rejected",!meta.SetLaws(new[]{"flux_radiance","flux_density"}));
  for(int i=0;i<3;i++){Check("megastructure starts "+i,meta.StartMega(i));}Advance(meta,ProgressionBalance.ConstructionBaseSeconds+1);Check("all three mega capabilities completed offline",meta.Meta.megas.All(m=>m.level==1));Check("parallel first universe",meta.CreateUniverse(1));Check("parallel second universe",meta.CreateUniverse(2));Check("capacity bounded",!meta.CreateUniverse(1));meta.EditUniverse(1,u=>u.S.automation.buy=false);meta.EditUniverse(2,u=>u.S.automation.buy=false);
  var u1=meta.Universe(1);var u2=meta.Universe(2);u1.S.resources[0]=new BigDouble(1000000);u2.S.resources[0]=new BigDouble(100);u1.S.paused[0]=u2.S.paused[0]=true;var total=u1.S.resources[0].Value+u2.S.resources[0].Value;var lifetime=u2.S.lifetime[0].Value;Check("bounded exchange schedule",meta.ScheduleTransfer(1,2,0));Advance(meta,3600);Check("transfer burns 20 percent and never creates lifetime",Near(u1.S.resources[0].Value+u2.S.resources[0].Value,total-10000)&&u2.S.lifetime[0].Value==lifetime);Check("exactly one transfer",meta.Meta.completedTransfers==1);var loaded=new Simulation(data,Clone(meta.S));Advance(loaded,1);Check("load does not repeat transfer",loaded.Meta.completedTransfers==1);
  var genesis=Mature();foreach(var m in genesis.Meta.megas)m.level=1;genesis.Meta.ascensionUpgrades.Add("a_energy_1");genesis.S.prestige[0]=new BigDouble(12);genesis.Meta.genesisUpgrades.Add("g_seed");Check("Genesis succeeds",genesis.Rebirth(2));Check("Genesis retention",genesis.S.prestige[0].Value==0&&genesis.S.prestige[1].Value==0&&genesis.Meta.ascensionUpgrades.Count==0&&genesis.Meta.genesisUpgrades.Contains("g_seed")&&genesis.S.owned[0]==8);
  var seed=new State();seed.owned[1]=2;seed.automation.buy=false;
  foreach(double span in new[]{3600d,21600d,86400d}){var s=new Simulation(data,Clone(seed));s.BeginOffline(span);while(s.S.offlineRemaining>0)s.ProcessOffline(32768);Check("unlimited offline "+span,s.S.resources.All(n=>n.Value>=0)&&Math.Abs(s.S.time-span)<.01);var report=s.S.offlineReport;Check("offline accounting "+span,Enumerable.Range(0,15).All(i=>Near(report.before[i].Value+report.produced[i].Value+report.granted[i].Value-report.spent[i].Value-report.resetLoss[i].Value,report.after[i].Value)));}
  foreach(double span in new[]{604800d,2592000d,31536000d}){var longQueue=new Simulation(data,Clone(seed));longQueue.BeginOffline(span);longQueue.ProcessOffline(10000);var continued=new Simulation(data,Clone(longQueue.S));Check("unlimited queue retains every remaining second after 10000 ticks / "+span,Math.Abs(continued.S.offlineRemaining+continued.S.offlineReport.processedSeconds-span)<.001&&continued.S.offlineRemaining>span-167&&continued.S.offlineReport.fixedTicks==10000);}
  var online=new Simulation(data,Clone(seed));var offline=new Simulation(data,Clone(seed));for(int i=0;i<36000;i++)FixedStepClock.Advance(online,1d/60);Advance(offline,600);Check("60 Hz and analytical same economy",Enumerable.Range(0,12).All(i=>Near(online.S.resources[i].Value,offline.S.resources[i].Value)));
  var slow=new Simulation(data,Clone(seed));for(int i=0;i<1800;i++)FixedStepClock.Advance(slow,1d/3);while(slow.S.liveRemaining>=FixedStepClock.Step)FixedStepClock.Advance(slow,0);Check("low render rate preserves elapsed production",Enumerable.Range(0,12).All(i=>Near(slow.S.resources[i].Value,online.S.resources[i].Value)));
  var a=new Simulation(data);var b=new Simulation(data);Advance(a,600);for(int i=0;i<36000;i++)FixedStepClock.Advance(b,1d/60);Check("autobuy deterministic fixed versus event step",a.S.owned.SequenceEqual(b.S.owned)&&Enumerable.Range(0,12).All(i=>Near(a.S.resources[i].Value,b.S.resources[i].Value)));
  var pending=new Simulation(data);pending.BeginOffline(31536000);pending.ProcessOffline(1);var restore=new Simulation(data,Clone(pending.S));Check("long offline cursor survives save",restore.S.offlineRemaining==pending.S.offlineRemaining&&restore.S.offlineRemaining>0);
  var paid=new Simulation(data,Clone(seed));paid.PremiumUntil=1e9;paid.BoostWindows.Add(new BoostWindow{start=0,end=1e9});Advance(paid,600);Check("legacy paid boost has zero production effect",Near(paid.S.resources[0].Value,offline.S.resources[0].Value));
  var huge=new Number(BigDouble.Parse("1e10000"));Check("huge precision round trip",JsonSerializer.Deserialize<Number>(JsonSerializer.Serialize(huge,J),J).Value==huge.Value);
  ExtraTests();PacingTests();ReadabilityTests();EvolutionTests();CadenceTests();DiscoveryTests();
  var watch=Stopwatch.StartNew();long bytes=GC.GetAllocatedBytesForCurrentThread();for(int i=0;i<600;i++)FixedStepClock.Advance(online,1d/60);watch.Stop();File.WriteAllText(Path.Combine(root,"Logs/Expansion/performance.json"),JsonSerializer.Serialize(new{logicalSteps=600,cpuMs=watch.Elapsed.TotalMilliseconds,allocatedBytes=GC.GetAllocatedBytesForCurrentThread()-bytes,visualFPS="UNVERIFIED - headless core only"},J));Check("bounded analytic history",online.History.Count<=120);
  var benchmarks=new List<object>();foreach(string stage in new[]{"early","middle","late"}){var bench=stage=="early"?new Simulation(data):Mature();bench.S.automation.buy=false;if(stage!="early"){for(int i=0;i<24;i++)bench.S.owned[i]=100;bench.S.purchases=data.upgrades.Concat(data.research).Select(u=>u.id).ToList();}if(stage=="late"){foreach(var m in bench.Meta.megas)m.level=6;bench.CreateUniverse(1);bench.CreateUniverse(2);bench.EditUniverse(1,u=>u.S.automation.buy=false);bench.EditUniverse(2,u=>u.S.automation.buy=false);}FixedStepClock.Advance(bench,1d/60);var timer=Stopwatch.StartNew();long allocated=GC.GetAllocatedBytesForCurrentThread();for(int i=0;i<600;i++)FixedStepClock.Advance(bench,1d/60);benchmarks.Add(new{stage,logicalSteps=600,cpuMs=timer.Elapsed.TotalMilliseconds,allocatedBytes=GC.GetAllocatedBytesForCurrentThread()-allocated,fixture=true,renderedFPS="UNVERIFIED"});}File.WriteAllText(Path.Combine(root,"Logs/Expansion/performance-stages.json"),JsonSerializer.Serialize(benchmarks,J));
