 static void ExtraTests(){
  var legacy=new State{version=1};legacy.talents.Add("t7");legacy.talents.Add("t8");SaveMigrations.Upgrade(legacy);Check("legacy talent spending reconstructed exactly",legacy.expansion.ascensionEarned.Value==9);
  var p=Mature();p.BuyMeta("a_energy_1");p.SetLaws(new[]{"flux_radiance"});p.S.owned[0]=20;p.S.owned[1]=4;p.Meta.records.Add("exchange-network");p.S.prestigePurchases.Add("p0_0");var unchanged=JsonSerializer.Serialize(p.S,J);var preview=p.PreviewRates(p.Meta.laws,p.Meta.ascensionUpgrades);p.RefreshRates();Check("rate preview preserves full original save",unchanged==JsonSerializer.Serialize(p.S,J));Check("current strategy preview matches actual flow",Enumerable.Range(0,12).All(i=>Near(preview[i].Value,p.CachedRate(i))));
  p.SaveStrategy(0);p.RespecAscension();p.BuyMeta("a_matter_1");p.Meta.lawReadyAt=0;var total=p.S.prestige[1].Value+1;var awarded=p.Meta.ascensionEarned.Value;Check("strategy apply succeeds",p.LoadStrategy(0));Check("strategy apply preserves invested total and earned record",p.S.prestige[1].Value+1==total&&p.Meta.ascensionEarned.Value==awarded&&p.HasA("a_energy_1"));Check("invalid imported strategy rejected",!p.ImportStrategy(0,new StrategyProfile{upgrades=new List<string>{"unknown"}}));
  var reserve=Mature();reserve.Meta.autoBuild=true;for(int i=0;i<24;i++)reserve.S.owned[i]=20;for(int slot=0;slot<3;slot++){int r=ExpansionContent.MegaResources[0][slot];reserve.S.resources[r]=reserve.MegaCost(0,slot)*(1-2e-15);}var timer=Stopwatch.StartNew();Advance(reserve,3600);Check("near-reserve rounding cannot stall analytical time",timer.Elapsed.TotalSeconds<5&&reserve.S.time==3600);Check("construction planner runs with autobuy disabled",reserve.Meta.megas[0].building||reserve.Meta.megas[0].level>0);
  var worlds=Mature();foreach(var m in worlds.Meta.megas)m.level=1;worlds.CreateUniverse(1);worlds.CreateUniverse(2);worlds.EditUniverse(1,u=>{u.S.automation.buy=false;u.S.owned[0]=20;});worlds.EditUniverse(2,u=>{u.S.automation.buy=false;u.S.owned[1]=5;});worlds.ScheduleTransfer(1,2,0);var fixture=Clone(worlds.S);Advance(worlds,3700);worlds.SettleUniverses();var worldLive=new Simulation(data,Clone(fixture));for(int i=0;i<222000;i++)FixedStepClock.Advance(worldLive,1d/60);worldLive.SettleUniverses();Check("parallel economy fixed and analytical agree",Enumerable.Range(1,2).All(id=>Enumerable.Range(0,12).All(r=>Near(worlds.Universe(id).S.resources[r].Value,worldLive.Universe(id).S.resources[r].Value))));
  var resumed=new Simulation(data,Clone(fixture));Advance(resumed,1800);resumed.SettleUniverses();resumed=new Simulation(data,Clone(resumed.S));Advance(resumed,1900);resumed.SettleUniverses();Check("parallel exchange save resume no duplication",resumed.Meta.completedTransfers==worlds.Meta.completedTransfers&&Enumerable.Range(1,2).All(id=>Enumerable.Range(0,12).All(r=>Near(worlds.Universe(id).S.resources[r].Value,resumed.Universe(id).S.resources[r].Value))));
  var challenge=Mature();Check("existing challenge starts",challenge.EnterChallenge(0));Check("meta reset rejected during challenge",!challenge.Rebirth(1));challenge.ExitChallenge();Check("challenge restores owned economy",challenge.S.resources[0].Value==BigDouble.Parse("1e18"));Check("existing expedition starts",challenge.StartVoyage(0));Advance(challenge,200000);Check("expedition claimed exactly once",challenge.Claim(challenge.S.voyages[0])&&!challenge.Claim(challenge.S.voyages[0]));
  var forged=Clone(fixture);forged.expansion.megas[0].work=double.NaN;try{new Simulation(data,forged);Check("corrupt meta time rejected",false);}catch(ArgumentException){Check("corrupt meta time rejected",true);}
 }
 static void Balance(){
  var result=new List<object>();
  double days=double.Parse(arguments.FirstOrDefault(a=>a.StartsWith("--days="))?.Substring(7)??"90",System.Globalization.CultureInfo.InvariantCulture);
  foreach(string strategy in new[]{"Energy","Matter","Time"}.Where(s=>!arguments.Any(a=>a.StartsWith("--strategy="))||arguments.Contains("--strategy="+s))){
   var s=new Simulation(data);double[] first={-1,-1,-1};double endgame=-1;int[] everMega=new int[3];var seen=new HashSet<string>();double nextVisit=0;int visits=0;
   var watch=Stopwatch.StartNew();while(s.S.time<days*86400-1e-6){
    bool firstSession=s.S.time<7200,checkIn=s.S.time+1e-6>=nextVisit;if(checkIn){visits++;nextVisit+=firstSession?900:43200;Choose(s,strategy);}
    if(checkIn)for(int layer=2;layer>=0;layer--)if(s.PrestigeReward(layer)>=1&&(layer>0||s.Meta.prestigeEarned.Value<ProgressionBalance.PrestigeForAscension)){if(s.Rebirth(layer)){if(first[layer]<0)first[layer]=s.S.time;break;}}
    if(checkIn&&arguments.Contains("--probe"))Console.WriteLine($"CHECK {strategy} day={s.S.time/86400:0.00} earned={s.Meta.prestigeEarned} stage3={s.StageOpen(3)} resets={string.Join(",",s.Meta.historicResets)} AP={s.Meta.ascensionEarned}");
    Advance(s,Math.Min(firstSession?60:3600,Math.Min(nextVisit-s.S.time,days*86400-s.S.time)));if(endgame<0&&s.HasG("g_horizon")&&s.UniverseCapacity==3)endgame=s.S.time;for(int i=0;i<3;i++)everMega[i]=Math.Max(everMega[i],s.Meta.megas[i].level);foreach(var p in s.S.purchases)seen.Add(p);
   }
   var row=new{strategy,firstPrestigeHours=first[0]/3600,firstAscensionDays=first[1]<0?-1:first[1]/86400,firstGenesisDays=first[2]<0?-1:first[2]/86400,mainContentDays=endgame<0?-1:endgame/86400,megas=everMega,universeCount=s.Meta.universes.Count+1,research=seen.Count,visits,simulationDays=s.S.time/86400,cpuSeconds=watch.Elapsed.TotalSeconds};result.Add(row);Console.WriteLine(JsonSerializer.Serialize(row));File.WriteAllText(Path.Combine(root,"Logs/Expansion/balance-"+strategy+"-save.json"),JsonSerializer.Serialize(s.S,J));
  }
  File.WriteAllText(Path.Combine(root,"Logs/Expansion/balance.json"),JsonSerializer.Serialize(result,J));
 }
 static void Choose(Simulation s,string strategy,bool campaign=false){
  foreach(var research in data.research)s.Purchase(research);for(int i=0;i<4;i++)s.PrestigeUpgrade(0,i);s.Meta.autoBuild=s.HasLayer(1);s.Meta.policy=strategy;s.S.automation.buy=true;s.Meta.guidedAutomation=true;s.Meta.autoResearch=s.HasA("a_time_2");
  foreach(var u in ExpansionContent.Ascension.Where(x=>x.branch==strategy))s.BuyMeta(u.id);foreach(var u in ExpansionContent.Genesis)s.BuyMeta(u.id,true);
  if(s.HasLayer(1)&&s.Meta.lawReadyAt<=s.S.time)s.SetLaws(strategy=="Energy"?new[]{"flux_radiance","time_patience"}:strategy=="Matter"?new[]{"flux_balance","space_fold"}:new[]{"time_burst","space_open"});
  if(s.HasLayer(0)){s.S.automation.repeatPrestige[0]=true;s.S.automation.prestigeThreshold=2;}
  for(int i=0;i<3;i++)if(!campaign||s.AllGenesisNodes||s.Meta.megas[i].level==0)s.StartMega(i);while(s.CreateUniverse(strategy=="Matter"?2:1)){};
 }
